import{_ as a,a as e,b as i,c as r}from"./chunks/network-diagram-3.DuVKc4J7.js";import{_ as o,o as d,c as s,a5 as n}from"./chunks/framework.DGp912Ge.js";const m=JSON.parse('{"title":"네트워크 구성도","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/interface/network.md","filePath":"ko/manual/interface/network.md","lastUpdated":1785806767000}'),l={name:"ko/manual/interface/network.md"};function c(h,t,p,P,u,b){return d(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="네트워크-구성도" tabindex="-1">네트워크 구성도 <a class="header-anchor" href="#네트워크-구성도" aria-label="Permalink to &quot;네트워크 구성도&quot;">​</a></h1><p>네트워크 구성은 로봇에 따라 다릅니다. 두 가지가 달라집니다.</p><ul><li><strong>구성</strong> — <strong>연구용</strong>은 User PC를 로봇 외부에 두고 페이로드를 하나의 LAN 그룹으로 묶습니다. <strong>산업용</strong>은 User PC를 로봇 내부에 탑재하고 페이로드를 각각 개별 연결합니다.</li><li><strong>라우터</strong> — 라우터가 <strong>스위치 허브에 통합된</strong> 로봇은 LTE/5G·Wi-Fi(Mesh) 모듈이 스위치 허브에 직접 연결됩니다. <strong>외장 라우터</strong>를 거치는 로봇도 있습니다.</li></ul><p>모든 구성도에서 <strong>R-PC</strong>는 로봇의 모션 PC, <strong>U-PC</strong>는 사용자 PC입니다. 초록 선은 LAN, 주황 선은 WAN입니다.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>네트워크 구성은 버전에 따라 다를 수 있습니다. 사용 중인 로봇의 구성이 확실하지 않은 경우 <a href="/RBQ/ko/manual/troubleshooting/error-reporting">문의 부탁드립니다</a>.</p></div></div><h2 id="연구용-구성" tabindex="-1">연구용 구성 <a class="header-anchor" href="#연구용-구성" aria-label="Permalink to &quot;연구용 구성&quot;">​</a></h2><p>U-PC가 로봇 외부에 있습니다. LAN 페이로드(LiDAR, PTZ 카메라, RTK GPS 등)는 스위치 허브에 하나의 연결을 공유합니다.</p><h3 id="라우터가-스위치-허브에-통합된-구성" tabindex="-1">라우터가 스위치 허브에 통합된 구성 <a class="header-anchor" href="#라우터가-스위치-허브에-통합된-구성" aria-label="Permalink to &quot;라우터가 스위치 허브에 통합된 구성&quot;">​</a></h3><figure><img src="'+a+'" alt="네트워크 구성도, 연구용 구성, 라우터가 스위치 허브에 통합"><figcaption style="text-align:center;">[ 연구용 · 라우터 통합 ]</figcaption></figure><h3 id="외장-라우터를-사용하는-구성" tabindex="-1">외장 라우터를 사용하는 구성 <a class="header-anchor" href="#외장-라우터를-사용하는-구성" aria-label="Permalink to &quot;외장 라우터를 사용하는 구성&quot;">​</a></h3><figure><img src="'+e+'" alt="네트워크 구성도, 연구용 구성, 외장 라우터 사용"><figcaption style="text-align:center;">[ 연구용 · 외장 라우터 ]</figcaption></figure><h2 id="산업용-구성" tabindex="-1">산업용 구성 <a class="header-anchor" href="#산업용-구성" aria-label="Permalink to &quot;산업용 구성&quot;">​</a></h2><p>U-PC가 R-PC와 함께 로봇 내부에 탑재되고, 페이로드(LiDAR 1, LiDAR 2, PTZ 카메라)가 각각 스위치 허브에 개별 연결됩니다.</p><h3 id="라우터가-스위치-허브에-통합된-구성-1" tabindex="-1">라우터가 스위치 허브에 통합된 구성 <a class="header-anchor" href="#라우터가-스위치-허브에-통합된-구성-1" aria-label="Permalink to &quot;라우터가 스위치 허브에 통합된 구성&quot;">​</a></h3><figure><img src="'+i+'" alt="네트워크 구성도, 산업용 구성, 라우터가 스위치 허브에 통합"><figcaption style="text-align:center;">[ 산업용 · 라우터 통합 ]</figcaption></figure><h3 id="외장-라우터를-사용하는-구성-1" tabindex="-1">외장 라우터를 사용하는 구성 <a class="header-anchor" href="#외장-라우터를-사용하는-구성-1" aria-label="Permalink to &quot;외장 라우터를 사용하는 구성&quot;">​</a></h3><figure><img src="'+r+'" alt="네트워크 구성도, 산업용 구성, 외장 라우터 사용"><figcaption style="text-align:center;">[ 산업용 · 외장 라우터 ]</figcaption></figure><p>이 구성에서는 LiDAR 2가 스위치 허브에 직접 연결되지 않고 라우터를 경유합니다.</p><h2 id="네트워크-상세" tabindex="-1">네트워크 상세 <a class="header-anchor" href="#네트워크-상세" aria-label="Permalink to &quot;네트워크 상세&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>Wi-Fi</td><td>2.4 GHz, 5 GHz</td></tr><tr><td>네트워크 스위치 속도</td><td>기가비트 이더넷 (1 Gbps)</td></tr><tr><td>Access Point</td><td><code>192.168.0.1</code></td></tr></tbody></table><h2 id="pc-구성-및-ip" tabindex="-1">PC 구성 및 IP <a class="header-anchor" href="#pc-구성-및-ip" aria-label="Permalink to &quot;PC 구성 및 IP&quot;">​</a></h2><p>Motion PC(R-PC)는 모든 로봇에 기본 탑재됩니다. Vision PC와 User PC(U-PC)는 옵션이며, 로봇 구성에 따라 탑재되지 않을 수 있습니다.</p><table tabindex="0"><thead><tr><th>PC</th><th>IP</th><th>역할</th><th>구성</th><th>사용자 접근</th></tr></thead><tbody><tr><td>Motion PC (R-PC)</td><td><code>192.168.0.10</code></td><td>로봇 제어</td><td>기본</td><td>불가</td></tr><tr><td>Vision PC</td><td><code>192.168.0.12</code></td><td>비전 처리</td><td>옵션</td><td>불가</td></tr><tr><td>User PC (U-PC)</td><td><code>192.168.0.13</code></td><td>사용자 개발 작업</td><td>옵션</td><td>가능</td></tr></tbody></table><p>Motion PC와 Vision PC는 로봇 동작에 직접 관여하므로 사용자가 접근할 수 없습니다. 사용자 개발 작업은 U-PC에서 수행합니다.</p><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">U-PC에 연결되지 않는 경우</p><p>U-PC의 기본 주소는 <code>192.168.0.13</code>입니다. 연결되지 않을 경우 U-PC에 모니터를 연결하여 현재 IP를 확인해 주세요. 다른 주소를 사용 중이라면 <code>192.168.0.13</code>으로 고정하여 사용해 주시기 바랍니다.</p></div></div>',25)])])}const C=o(l,[["render",c]]);export{m as __pageData,C as default};
